sysauto_script.script:
(function executeRule() {

    // Find records where expiry is exactly 30 days from today
    var gr = new GlideRecord("x_vuram_financia_0_fcc_kyc_individual_details"); // table name
    var targetDate = new GlideDateTime();
    targetDate.addDaysLocalTime(30); // add 30 days

    gr.addQuery("poi_doc_expiry_date", targetDate.getDate()); // expiry date = today + 30
    gr.query();

    while (gr.next()) {
        // Fire the event for 30 days prior notification
        gs.eventQueue("x_vuram_financia_0.kyc.expiry.30days", gr, "", "");

        gs.info("30 days prior KYC expiry notification fired for record: " + gr.sys_id);
    }

})();
